import sqlite3

def run(script):
    con = sqlite3.connect(":memory:")
    con.executescript("""
        CREATE TABLE campaigns(campaign_id INTEGER, name TEXT);
        CREATE TABLE clicks(click_id INTEGER, campaign_id INTEGER);
        CREATE TABLE orders(order_id INTEGER, campaign_id INTEGER, amount REAL);
    """ + script)
    return con.execute(QUERY).fetchall()

DATA_A = """
    INSERT INTO campaigns VALUES (1, 'spring'), (2, 'summer'), (3, 'autumn');
    INSERT INTO clicks VALUES (1, 1), (2, 1), (3, 1), (4, 2);
    INSERT INTO orders VALUES (1, 1, 10.0), (2, 1, 20.0), (3, 3, 5.5);
"""

DATA_B = """
    INSERT INTO campaigns VALUES (10, 'promo'), (20, 'retarget'), (30, 'empty');
    INSERT INTO clicks VALUES (1, 10), (2, 10), (3, 20), (4, 20), (5, 20);
    INSERT INTO orders VALUES (1, 10, 100.0), (2, 10, 50.25), (3, 10, 0.5), (4, 20, 7.0), (5, 20, 3.0);
"""

assert run(DATA_A) == [(1, "spring", 3, 30.0), (2, "summer", 1, 0.0), (3, "autumn", 0, 5.5)], "Небольшой пример: без раздувания и с нулями"
assert run(DATA_B) == [(10, "promo", 2, 150.75), (20, "retarget", 3, 10.0), (30, "empty", 0, 0.0)], "Много кликов и заказов у одной кампании"
assert len(run(DATA_B)) == 3, "Каждая кампания ровно один раз"

