import json
class FakeRedis:
    def __init__(self):
        self.now = 0.0
        self.data = {}
    def get(self, key):
        item = self.data.get(key)
        if item is None:
            return None
        value, expires_at = item
        if expires_at is not None and self.now >= expires_at:
            del self.data[key]
            return None
        return value
    def set(self, key, value, ex=None):
        self.data[key] = (value, None if ex is None else self.now + ex)
        return True
r = FakeRedis()
calls = {"n": 0}
@cached(r, ttl=60)
def predict(user_id, boost=1.0):
    calls["n"] += 1
    return {"user": user_id, "score": 0.5 * boost}
assert predict(42) == {"user": 42, "score": 0.5}, "Первый вызов считает результат"
assert predict(42) == {"user": 42, "score": 0.5}, "Второй вызов берёт из кэша"
assert calls["n"] == 1, "Функция вызвана один раз"
assert predict(7) == {"user": 7, "score": 0.5} and calls["n"] == 2, "Другие аргументы — промах"
assert all(isinstance(v, str) for v, _ in r.data.values()), "В Redis кладём JSON-строку, а не Python-объект"
assert all(exp == 60 for _, exp in r.data.values()), "TTL передан как ex=ttl"
r.now = 61
assert predict(42) == {"user": 42, "score": 0.5} and calls["n"] == 3, "После TTL значение пересчитывается"
predict(user_id=1, boost=2.0)
predict(boost=2.0, user_id=1)
assert calls["n"] == 4, "Порядок kwargs не влияет на ключ"

class FakeRedis:
    def __init__(self):
        self.now = 0.0
        self.data = {}
        self.exp = {}
    def _purge(self, key):
        if key in self.exp and self.now >= self.exp[key]:
            self.data.pop(key, None)
            self.exp.pop(key, None)
    def incr(self, key):
        self._purge(key)
        self.data[key] = self.data.get(key, 0) + 1
        return self.data[key]
    def expire(self, key, seconds):
        self._purge(key)
        if key not in self.data:
            return False
        self.exp[key] = self.now + seconds
        return True
    def ttl(self, key):
        self._purge(key)
        if key not in self.data:
            return -2
        return -1 if key not in self.exp else int(self.exp[key] - self.now)
def call(r, user, t, limit=3, window=60):
    r.now = t
    return allow(r, user, limit, window, t)
r = FakeRedis()
assert [call(r, "u1", t) for t in (0, 1, 2)] == [True, True, True], "Первые 3 запроса в окне проходят"
assert call(r, "u1", 3) is False, "4-й запрос в том же окне отклонён"
assert call(r, "u1", 59) is False, "До конца окна лимит исчерпан"
assert r.ttl("rl:u1:0") > 0, "У счётчика окна есть TTL"
assert call(r, "u1", 60) is True, "Новое окно — новый счётчик"
assert call(r, "u2", 3) is True, "Лимит считается для каждого пользователя отдельно"
r2 = FakeRedis()
burst = [call(r2, "u3", 59.5) for _ in range(3)] + [call(r2, "u3", 60.0) for _ in range(3)]
assert burst == [True] * 6, "Недостаток окна: на стыке окон за 0.5 с проходит 2 * limit запросов"

class FakeRedis:
    def __init__(self):
        self.z = {}
        self.ttls = {}
    def zremrangebyscore(self, key, mn, mx):
        s = self.z.get(key, {})
        drop = [m for m, sc in s.items() if mn <= sc <= mx]
        for m in drop:
            del s[m]
        return len(drop)
    def zcard(self, key):
        return len(self.z.get(key, {}))
    def zadd(self, key, mapping):
        s = self.z.setdefault(key, {})
        added = sum(1 for m in mapping if m not in s)
        s.update(mapping)
        return added
    def expire(self, key, seconds):
