import json
class FakeRedis:
    def __init__(self):
        self.now = 0.0
        self.data = {}
    def _alive(self, key):
        item = self.data.get(key)
        if item is None:
            return None
        if item[1] is not None and self.now >= item[1]:
            del self.data[key]
            return None
        return item
    def get(self, key):
        item = self._alive(key)
        return None if item is None else item[0]
    def set(self, key, value, ex=None, nx=False):
        if nx and self._alive(key) is not None:
            return None
        self.data[key] = (value, None if ex is None else self.now + ex)
        return True
    def delete(self, key):
        return 1 if self.data.pop(key, None) is not None else 0
r = FakeRedis()
calls = {"n": 0}
def compute():
    calls["n"] += 1
    return {"top": [1, 2, 3]}
